const recent = members.filter(m => (m.joined_days_ago ?? 999) < 7);
for (const m of recent) {
  m.add_role("Newcomer");
}
return [
  title("Tagged"),
  footer(`${recent.length} members`)
];

input.role("role", "Pick the role to count");
const role = find_role(form.role);
if (!role) {
  fail_input("That role no longer exists — pick another.");
}
return [
  title(`Members with ${role.name}`),
  { count: members_with_role(role.id).length }
];
